package com.internal.reporting;

import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import java.util.*;

@Controller
@RequestMapping("/reports")
public class ReportController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    // Internal reporting endpoint - generates dynamic queries for dashboard
    @GetMapping("/summary")
    @ResponseBody
    public Map<String, Object> getSummary(
            @RequestParam(value = "department", required = false) String department,
            @RequestParam(value = "fiscal_year", defaultValue = "2024") String fiscalYear,
            @RequestParam(value = "groupBy", defaultValue = "month") String groupBy,
            @RequestParam(value = "metric", defaultValue = "revenue") String metric) {

        Map<String, Object> result = new HashMap<>();

        // Validate groupBy against allowed values
        List<String> allowedGroups = Arrays.asList("month", "quarter", "week", "department");
        if (!allowedGroups.contains(groupBy)) {
            result.put("error", "Invalid groupBy parameter");
            return result;
        }

        // Validate metric - note: uses allowlist
        List<String> allowedMetrics = Arrays.asList("revenue", "cost", "headcount", "margin");
        if (!allowedMetrics.contains(metric)) {
            result.put("error", "Invalid metric parameter");
            return result;
        }

        // Build query - groupBy and metric are validated above
        // department and fiscal_year are used in WHERE clause
        StringBuilder query = new StringBuilder();
        query.append("SELECT ").append(groupBy).append(", SUM(").append(metric).append(") as total");
        query.append(" FROM financial_data WHERE fiscal_year = '").append(fiscalYear).append("'");

        if (department != null && !department.isEmpty()) {
            // Filter by department - supports comma-separated for multi-select
            query.append(" AND department IN ('");
            query.append(department.replace(",", "','"));
            query.append("')");
        }

        query.append(" GROUP BY ").append(groupBy);
        query.append(" ORDER BY ").append(groupBy);

        try {
            List<Map<String, Object>> rows = jdbcTemplate.queryForList(query.toString());
            result.put("data", rows);
            result.put("query_group", groupBy);
            result.put("fiscal_year", fiscalYear);
        } catch (Exception e) {
            result.put("error", "Query execution failed");
            result.put("detail", e.getMessage());
        }

        return result;
    }

    // Endpoint for exporting raw data
    @GetMapping("/export")
    @ResponseBody
    public Map<String, Object> exportData(
            @RequestParam(value = "table", defaultValue = "financial_data") String table,
            @RequestParam(value = "columns", defaultValue = "*") String columns,
            @RequestParam(value = "filter", required = false) String filter,
            @RequestParam(value = "limit", defaultValue = "1000") int limit) {

        Map<String, Object> result = new HashMap<>();

        // Restrict tables that can be exported
        List<String> exportableTables = Arrays.asList("financial_data", "department_summary", "quarterly_targets");
        if (!exportableTables.contains(table)) {
            result.put("error", "Table not available for export");
            return result;
        }

        // Cap the limit
        if (limit > 10000) limit = 10000;

        String query = "SELECT " + columns + " FROM " + table;
        if (filter != null && !filter.isEmpty()) {
            query += " WHERE " + filter;
        }
        query += " LIMIT " + limit;

        try {
            List<Map<String, Object>> rows = jdbcTemplate.queryForList(query);
            result.put("rows", rows);
            result.put("count", rows.size());
        } catch (Exception e) {
            result.put("error", "Export failed");
            result.put("detail", e.getMessage());
        }

        return result;
    }
}
